let Lenis = null;
let lenis = null;
import('../vendor/lenis.min.mjs').then(mod => {
  Lenis = mod.default || mod.Lenis;
  if (Lenis) {
    try {
      lenis = new Lenis({
        duration: 1.1,
        easing: (t) => Math.min(1, 1.001 - Math.pow(2, -10 * t)),
        orientation: 'vertical',
        smoothWheel: true
      });
      window.__lenis = lenis;
      function raf(time) {
        lenis.raf(time);
        requestAnimationFrame(raf);
      }
      requestAnimationFrame(raf);
    } catch(err) {
      console.warn('Lenis run fallback', err);
    }
  }
}).catch(err => {
  console.warn('Lenis non-critical import fallback', err);
});

const COLOUR_SRC = "data:image/webp;base64,";
const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];
const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
const root = document.documentElement;

/* ================== ADAPTIVE GRID SCALE ================== */
function applyAdaptiveGrid() {
  const FONT_BASE = 16, baseWidth = 1920, coef = 0.6666;
  const w = window.innerWidth;
  const widthReduction = ((baseWidth - w) / baseWidth) * 100;
  const size = FONT_BASE - (FONT_BASE * (widthReduction * coef)) / 100;
  if (size > FONT_BASE) root.style.fontSize = size + 'px';
  else root.style.removeProperty('font-size');
}
applyAdaptiveGrid();
window.addEventListener('resize', applyAdaptiveGrid);

/* Lenis initialized non-blocking above */

/* ================== LIVE CLOCK & FOOTER FIT ================== */
function tickClock() {
  const d = new Date();
  // Format Indian Standard Time (IST)
  const options = { timeZone: 'Asia/Kolkata', hour: '2-digit', minute: '2-digit', hour12: true };
  const timeStr = d.toLocaleTimeString('en-US', options).toLowerCase();
  $$('[data-ftime]').forEach(el => el.textContent = timeStr);
  $$('[data-fyear]').forEach(el => el.textContent = d.getFullYear());
}
tickClock();
setInterval(tickClock, 15000);

function fitFooterName() {
  const f = $('.sf');
  if (!f) return;
  const w = f.querySelector('.sf__word');
  if (!w) return;
  const span = w.firstElementChild;
  if (!span) return;
  w.style.setProperty('--wf', '100px');
  const k = (f.clientWidth * 0.95) / span.getBoundingClientRect().width;
  f.style.setProperty('--wf', (100 * k).toFixed(2) + 'px');
  w.style.removeProperty('--wf');
}
fitFooterName();
window.addEventListener('resize', fitFooterName);
document.fonts?.ready.then(fitFooterName);

/* ================== THEME TOGGLE (LIGHT / DARK) ================== */
const MODE_KEY = 'vivek-mode';
function getMode() { return root.dataset.mode === 'dark' ? 'dark' : 'light'; }
let pendingMode = null;
function setMode(m) {
  if ((pendingMode || getMode()) === m) return;
  const apply = () => {
    root.dataset.mode = m;
    pendingMode = null;
    const meta = $('meta[name=theme-color]');
    if (meta) meta.setAttribute('content', m === 'dark' ? '#1A1818' : '#E8E4E0');
    window.dispatchEvent(new CustomEvent('themechange', { detail: m }));
  };
  if (document.startViewTransition && !window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    pendingMode = m;
    document.startViewTransition(apply);
  } else {
    apply();
  }
  try { localStorage.setItem(MODE_KEY, m); } catch (e) {}
}
const toggleMode = () => setMode((pendingMode || getMode()) === 'dark' ? 'light' : 'dark');

/* ================== VERLET PHYSICS PULL CORD ================== */
(() => {
  const cord = $('#cord');
  if (!cord) return;
  const cv = cord.querySelector('.cord__cv');
  const hit = cord.querySelector('.cord__hit');
  const c = cv.getContext('2d');
  let W = 120, H = 240, dpr = Math.min(2, window.devicePixelRatio || 1);
  const N = 12, SEG_LEN = 12;
  const pts = [];
  for (let i = 0; i <= N; i++) {
    pts.push({ x: W / 2, y: 15 + i * SEG_LEN, px: W / 2, py: 15 + i * SEG_LEN, w: i === 0 ? 0 : 1 });
  }
  let anchor = { x: W / 2, y: 15 };
  let dragging = false, pointerDown = false, moved = false, suppressClick = false, grabIdx = -1;
  let ptr = { x: W / 2, y: 15 + N * SEG_LEN };
  let pointerStart = { x: 0, y: 0 }, knobStart = { ...ptr };
  let anchorY = 15;
  const PULL_THRESHOLD = 44;
  let triggered = false;

  const size = () => {
    dpr = Math.min(2, window.devicePixelRatio || 1);
    W = cv.clientWidth || 120;
    H = cv.clientHeight || 240;
    cv.width = W * dpr;
    cv.height = H * dpr;
    anchor.x = W / 2;
  };
  size();
  window.addEventListener('resize', size);

  function physics() {
    const grav = 0.38, damp = 0.94;
    // Anchor spring
    const targetAnchorY = dragging ? Math.min(anchorY + 12, 15 + 16) : 15;
    anchorY += (targetAnchorY - anchorY) * 0.2;
    anchor.x = W / 2 + Math.sin(performance.now() * 0.0014) * 1.25;
    pts[0].x = anchor.x;
    pts[0].y = anchorY;

    for (let i = 1; i <= N; i++) {
      const p = pts[i];
      if (dragging && i === grabIdx) {
        p.px = p.x; p.py = p.y;
        p.x = ptr.x; p.y = ptr.y;
        continue;
      }
      const vx = (p.x - p.px) * damp;
      const vy = (p.y - p.py) * damp + grav;
      p.px = p.x; p.py = p.y;
      p.x += vx; p.y += vy;
    }

    // Relax constraints (distance)
    for (let iter = 0; iter < 6; iter++) {
      for (let i = 0; i < N; i++) {
        const p1 = pts[i], p2 = pts[i + 1];
        const dx = p2.x - p1.x, dy = p2.y - p1.y;
        const dist = Math.hypot(dx, dy) || 1e-4;
        const diff = (dist - SEG_LEN) / dist;
        const w1 = i === 0 ? 0 : 0.5;
        const w2 = (dragging && i + 1 === grabIdx) ? 0 : 0.5;
        p1.x += dx * diff * w1;
        p1.y += dy * diff * w1;
        p2.x -= dx * diff * w2;
        p2.y -= dy * diff * w2;
      }
    }

  }

  function draw() {
    c.setTransform(dpr, 0, 0, dpr, 0, 0);
    c.clearRect(0, 0, W, H);

    // Draw rope
    c.beginPath();
    c.moveTo(pts[0].x, pts[0].y);
    for (let i = 1; i <= N; i++) {
      const p0 = pts[i - 1], p1 = pts[i];
      const mx = (p0.x + p1.x) / 2, my = (p0.y + p1.y) / 2;
      c.quadraticCurveTo(p0.x, p0.y, mx, my);
    }
    c.lineTo(pts[N].x, pts[N].y);
    c.strokeStyle = getMode() === 'dark' ? '#857878' : '#6B5C5C';
    c.lineWidth = 3.5;
    c.lineCap = 'round';
    c.stroke();

    // Knob (turned walnut + brass ferrule)
    const end = pts[N];
    const prev = pts[N - 1];
    const ang = Math.atan2(end.y - prev.y, end.x - prev.x) - Math.PI / 2;

    c.save();
    c.translate(end.x, end.y);
    c.rotate(ang);

    // Brass ferrule
    c.fillStyle = '#D6B26E';
    c.fillRect(-4, 0, 8, 5);

    // Walnut body
    c.beginPath();
    c.ellipse(0, 14, 6.5, 11, 0, 0, Math.PI * 2);
    c.fillStyle = getMode() === 'dark' ? '#C4B0B0' : '#2A2220';
    c.fill();
    c.strokeStyle = '#D6B26E';
    c.lineWidth = 1;
    c.stroke();

    c.restore();
  }

  function loop() {
    physics();
    draw();
    requestAnimationFrame(loop);
  }
  loop();

  function getPos(e) {
    const r = cv.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  }

  hit.addEventListener('pointerdown', (e) => {
    if (e.button !== 0 && e.pointerType === 'mouse') return;
    hit.setPointerCapture(e.pointerId);
    pointerDown = true;
    dragging = true;
    grabIdx = N;
    moved = false;
    triggered = false;
    pointerStart = getPos(e);
    knobStart = { x: pts[N].x, y: pts[N].y };
    ptr = { ...knobStart };
  });

  hit.addEventListener('pointermove', (e) => {
    if (!pointerDown) return;
    const pos = getPos(e);
    const dx = pos.x - pointerStart.x;
    const dy = pos.y - pointerStart.y;
    if (Math.hypot(dx, dy) > 5) moved = true;
    ptr = { x: knobStart.x + dx, y: knobStart.y + Math.max(0, dy) };
    if (!triggered && dy >= PULL_THRESHOLD) {
      triggered = true;
      toggleMode();
      if (navigator.vibrate) navigator.vibrate(25);
    }
  });

  function releasePull(e) {
    if (!pointerDown) return;
    pointerDown = false;
    dragging = false;
    grabIdx = -1;
    suppressClick = moved;
    if (hit.hasPointerCapture(e.pointerId)) hit.releasePointerCapture(e.pointerId);
    window.setTimeout(() => { suppressClick = false; }, 0);
  }
  hit.addEventListener('pointerup', releasePull);
  hit.addEventListener('pointercancel', releasePull);

  hit.addEventListener('click', (e) => {
    if (suppressClick) {
      e.preventDefault();
      suppressClick = false;
      return;
    }
    pts[N].py -= 28;
    toggleMode();
  });
})();

/* ================== 3D FLIP CALENDAR (SKILLS) ================== */
(() => {
  const cal = $('#cal');
  if (!cal) return;
  const words = [
    'Full-Stack Developer',
    'Generative AI Engineer',
    'MERN Stack Developer',
    'Problem Solver (DSA)'
  ];
  let cur = 0;
  const underWord = cal.querySelector('[data-under] .cal__word');
  const faceWord = cal.querySelector('.cal__face .cal__word');
  const rearWord = cal.querySelector('.cal__rear .cal__word');
  const body = cal.querySelector('.cal__body');
  const measure = cal.querySelector('.cal__measure');
  const wordEls = $$('.cal__word', cal);
  const leaf = cal.querySelector('.cal__leaf');

  function fit(wStr) {
    measure.textContent = wStr;
    const w = measure.offsetWidth;
    const fontSize = parseFloat(getComputedStyle(cal).fontSize);
    const maxWidth = Math.max(7 * 16, cal.parentElement.clientWidth * .92);
    const scale = Math.min(1, (maxWidth - fontSize * 1.4) / w);
    const wordFontSize = fontSize * scale;
    wordEls.forEach(word => { word.style.fontSize = scale < 1 ? wordFontSize + 'px' : ''; });
    body.style.width = Math.max(7 * 16, Math.min(maxWidth, w * scale + wordFontSize * 1.4)) + 'px';
  }

  function setInitial() {
    faceWord.textContent = words[0];
    rearWord.textContent = words[1];
    underWord.textContent = words[1];
    fit(words[0]);
  }
  setInitial();
  window.addEventListener('resize', () => requestAnimationFrame(() => fit(words[cur])));

  function flip() {
    const next = (cur + 1) % words.length;
    const afterNext = (next + 1) % words.length;

    underWord.textContent = words[next];
    rearWord.textContent = words[next];
    fit(words[next]);

    leaf.style.transition = 'transform 0.65s cubic-bezier(0.2, 0.8, 0.2, 1)';
    leaf.style.transform = 'rotateX(-180deg)';

    setTimeout(() => {
      leaf.style.transition = 'none';
      leaf.style.transform = 'rotateX(0deg)';
      faceWord.textContent = words[next];
      cur = next;
      rearWord.textContent = words[afterNext];
      underWord.textContent = words[afterNext];
    }, 680);
  }

  setInterval(flip, 3200);
})();

/* ================== LIQUID REVEAL HERO PORTRAIT ================== */
(() => {
  const fig = $('#fig');
  const cv = $('#figCanvas');
  const baseImg = $('#figBase');
  if (!fig || !cv || !baseImg) return;
  const ctx = cv.getContext('2d');
  let W = 0, H = 0, dpr = Math.min(2, window.devicePixelRatio || 1);

  const colorImg = new Image();
  colorImg.src = COLOUR_SRC;

  const size = () => {
    dpr = Math.min(2, window.devicePixelRatio || 1);
    W = fig.clientWidth;
    H = fig.clientHeight;
    cv.width = W * dpr;
    cv.height = H * dpr;
    ctx.scale(dpr, dpr);
  };
  baseImg.onload = size;
  size();
  window.addEventListener('resize', size);

  const stamps = [];
  function stamp(x, y) {
    stamps.push({ x, y, r: 120, life: 1.0 });
  }

  fig.addEventListener('pointermove', (e) => {
    const r = fig.getBoundingClientRect();
    const x = e.clientX - r.left;
    const y = e.clientY - r.top;
    stamp(x, y);
  });

  function render() {
    if (!colorImg.complete || !colorImg.naturalWidth) {
      requestAnimationFrame(render);
      return;
    }
    ctx.clearRect(0, 0, W, H);

    for (let i = stamps.length - 1; i >= 0; i--) {
      const s = stamps[i];
      s.life -= 0.022;
      if (s.life <= 0) {
        stamps.splice(i, 1);
        continue;
      }
      ctx.save();
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r * (1 + (1 - s.life) * 0.4), 0, Math.PI * 2);
      ctx.clip();
      ctx.globalAlpha = Math.sin(s.life * Math.PI * 0.5);
      ctx.drawImage(colorImg, 0, 0, W, H);
      ctx.restore();
    }
    requestAnimationFrame(render);
  }
  requestAnimationFrame(render);
})();

/* ================== HERO MINI SLIDER ================== */
(() => {
  const card = $('#hcard');
  if (!card) return;
  const slides = $$('.slide', card);
  const dots = $$('#hdots i', card);
  let cur = 0;

  function show(idx) {
    cur = (idx + slides.length) % slides.length;
    slides.forEach((s, i) => {
      s.style.opacity = i === cur ? '1' : '0';
      s.style.transform = i === cur ? 'none' : 'translateY(8px)';
    });
    dots.forEach((d, i) => d.classList.toggle('on', i === cur));
  }

  card.querySelector('.rnd--next')?.addEventListener('click', (e) => { e.stopPropagation(); show(cur + 1); });
  card.querySelector('.rnd--prev')?.addEventListener('click', (e) => { e.stopPropagation(); show(cur - 1); });
  card.querySelector('.hcard__row')?.addEventListener('click', () => show(cur + 1));
  setInterval(() => show(cur + 1), 4000);
})();

