/* LeetCode live stats (public profile). Edit LC_USER or LC_FALLBACK below. If the free stats API is down,
   the fallback numbers are shown instead; set them to your real numbers: {total:0,easy:0,medium:0,hard:0}. */
const LC_USER = 'vivek_pundkar';
const LC_FALLBACK = null;
const LC_HTML = `<div class="lc"><div class="lc__top"><div class="lc__big"><b data-lc="total">—</b><span>problems solved</span></div><p class="lc__note" data-lc="note">Loading live stats…</p></div>
  <div class="lc__row"><div class="lc__c lc__e"><b data-lc="easy">—</b><span>Easy</span><i data-lc="easyBar"></i></div><div class="lc__c lc__m"><b data-lc="medium">—</b><span>Medium</span><i data-lc="mediumBar"></i></div><div class="lc__c lc__h"><b data-lc="hard">—</b><span>Hard</span><i data-lc="hardBar"></i></div></div></div>`;
async function initLC() {
  const q = k => document.querySelector('[data-lc="' + k + '"]');
  if (!q('total')) return;
  const show = (d, live) => {
    const total = d.total || (d.easy + d.medium + d.hard) || 1;
    ['total', 'easy', 'medium', 'hard'].forEach(k => {
      const el = q(k), to = d[k] || 0, t0 = performance.now();
      const step = t => { const p = Math.min((t - t0) / 1200, 1); el.textContent = Math.round(to * (1 - Math.pow(1 - p, 3))); if (p < 1) requestAnimationFrame(step); };
      requestAnimationFrame(step);
    });
    ['easy', 'medium', 'hard'].forEach(k => { q(k + 'Bar').style.setProperty('--w', Math.round((d[k] || 0) / total * 100) + '%'); });
    q('note').textContent = live ? 'Live from LeetCode' : 'Open my profile for the latest numbers';
  };
  const tries = [
    async () => { const r = await (await fetch('https://leetcode-stats-api.herokuapp.com/' + LC_USER)).json(); if (r.status !== 'success') throw 0; return { total: r.totalSolved, easy: r.easySolved, medium: r.mediumSolved, hard: r.hardSolved }; },
    async () => { const r = await (await fetch('https://alfa-leetcode-api.onrender.com/' + LC_USER + '/solved')).json(); if (r.solvedProblem == null) throw 0; return { total: r.solvedProblem, easy: r.easySolved, medium: r.mediumSolved, hard: r.hardSolved }; }
  ];
  for (const t of tries) { try { show(await t(), true); return; } catch (e) { /* try next source */ } }
  if (LC_FALLBACK) show(LC_FALLBACK, false);
  else { document.querySelector('.lc')?.classList.add('lc--off'); q('note').textContent = 'Live stats could not load right now. Open my LeetCode profile below to see my latest solved count.'; ['total', 'easy', 'medium', 'hard'].forEach(k => q(k).textContent = '—'); }
}

(() => {
  const units = $$('.unit');
  const dinfo = $('#dinfo');
  const roomv = $('#roomv');
  const roomClose = $('#roomClose');
  const roomCards = $('#roomCards');
  const roomTitle = $('#roomTitle');
  const roomDesc = $('#roomDesc');
  const roomDoorNum = $('#roomDoorNum');
  const roomGlow = $('#roomGlow');
  const doorsSection = $('#works');
  const doorDots = $$('.doors__dots i', doorsSection);
  let mobileDoorIndex = -1;
  let mobileDoorFrame = 0;
  let mobileRowOffset = 0;

  function renderDoorInfo(info) {
    if (!dinfo) return;
    dinfo.querySelector('.dinfo__h').textContent = info.headline;
    dinfo.querySelector('.dinfo__t').textContent = info.subtitle;
    dinfo.querySelector('.dinfo__p').innerHTML = info.bullets.map(b => '<li>' + b + '</li>').join('');
    dinfo.style.setProperty('--dinfo-accent', info.theme);
    dinfo.classList.add('on');
  }

  function updateMobileDoorInfo() {
    const row = doorsSection?.querySelector('.doors__row');
    if (innerWidth > 639.98) {
      if (mobileRowOffset !== 0) {
        row.style.transform = '';
        mobileRowOffset = 0;
      }
      return;
    }
    if (roomv.classList.contains('open')) return;
    const pin = doorsSection?.querySelector('.doors__pin');
    const bounds = pin?.getBoundingClientRect();
    if (!bounds || bounds.bottom <= 0 || bounds.top >= innerHeight) return;

    const center = innerWidth / 2;
    const visibleUnits = units.filter(unit => getComputedStyle(unit).display !== 'none');
    let nearest = -1;
    if (innerHeight > 500) {
      const sectionTop = doorsSection.getBoundingClientRect().top + scrollY;
      const travel = Math.max(0, doorsSection.offsetHeight - pin.offsetHeight);
      const step = travel / visibleUnits.length;
      nearest = Math.min(visibleUnits.length - 1, Math.floor(Math.max(0, scrollY - sectionTop) / step));

      const target = visibleUnits[nearest].getBoundingClientRect();
      const targetCenter = target.left + target.width / 2 - mobileRowOffset;
      mobileRowOffset = center - targetCenter;
      row.style.transform = `translate3d(${mobileRowOffset}px, 0, 0)`;
    } else {
      if (mobileRowOffset !== 0) {
        row.style.transform = '';
        mobileRowOffset = 0;
      }
      let distance = Infinity;
      visibleUnits.forEach((unit) => {
        const index = units.indexOf(unit);
        const rect = unit.getBoundingClientRect();
        const horizontalDistance = rect.left + rect.width / 2 - center;
        const verticalDistance = rect.top + rect.height / 2 - innerHeight / 2;
        const nextDistance = Math.hypot(horizontalDistance, verticalDistance);
        if (nextDistance < distance) {
          nearest = index;
          distance = nextDistance;
        }
      });
    }
    if (nearest < 0 || nearest === mobileDoorIndex) return;

    mobileDoorIndex = nearest;
    units.forEach((unit, index) => unit.classList.toggle('on', index === nearest));
    doorDots.forEach((dot, index) => dot.classList.toggle('on', index === nearest));
    renderDoorInfo(DOORS_INFO[nearest]);
  }

  function queueMobileDoorInfo() {
    if (mobileDoorFrame) return;
    mobileDoorFrame = requestAnimationFrame(() => {
      mobileDoorFrame = 0;
      updateMobileDoorInfo();
    });
  }
  window.addEventListener('scroll', queueMobileDoorInfo, { passive: true });
  window.addEventListener('resize', queueMobileDoorInfo);

  units.forEach((u, i) => {
    const info = DOORS_INFO[i];
    const btn = u.querySelector('.doorway');

    // Hover info card
    btn.addEventListener('pointerenter', () => {
      renderDoorInfo(info);
    });

    btn.addEventListener('pointermove', (e) => {
      if (!dinfo) return;
      const w = dinfo.offsetWidth || 300, hh = dinfo.offsetHeight || 200;
      let x = e.clientX + 28;
      if (x + w > innerWidth - 16) x = e.clientX - w - 28;
      const y = Math.max(84, Math.min(innerHeight - hh - 16, e.clientY - hh / 2));
      dinfo.style.left = x + 'px'; dinfo.style.top = y + 'px';
    });

    btn.addEventListener('pointerleave', () => {
      dinfo?.classList.remove('on');
    });

    // Open Skill Room
    btn.addEventListener('click', () => openRoom(i, u));
  });

  // Popover menu links to doors
  $$('[data-door]').forEach(link => {
    link.addEventListener('click', (e) => {
      e.preventDefault();
      const idx = parseInt(link.dataset.door, 10);
      openRoom(idx, units[idx]);
    });
  });

  function openRoom(i, unit) {
    const info = DOORS_INFO[i];
    roomDoorNum.textContent = info.num;
    roomTitle.textContent = info.headline;
    roomDesc.textContent = info.subtitle;
    roomGlow.style.setProperty('--rg', info.theme);

    roomCards.innerHTML = info.projects.map(p => `
      <div class="proj-card${p.kind === 'leetcode' ? ' lc-card' : ''}${p.feat ? ' feat' : ''}">
        <div>
          <span class="proj-badge">${p.badge}</span>
          <h3 class="proj-title">${p.title}</h3>
          <p class="proj-desc">${p.desc}</p>
          ${p.kind === 'leetcode' ? LC_HTML : ''}
          <ul class="proj-bullets">
            ${p.bullets.map(b => '<li>' + b + '</li>').join('')}
          </ul>
          <div class="proj-tags">
            ${p.tags.map(t => '<span class="proj-tag">' + t + '</span>').join('')}
          </div>
        </div>
        <div class="proj-actions">
          <a class="proj-link" href="${p.link}" target="_blank" rel="noopener">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 19c-5 1.5-5-2.5-7-3m14 6v-3.87a3.37 3.37 0 0 0-.94-2.61c3.14-.35 6.44-1.54 6.44-7A5.44 5.44 0 0 0 20 4.77 5.07 5.07 0 0 0 19.91 1S18.73.65 16 2.48a13.38 13.38 0 0 0-7 0C6.27.65 5.09 1 5.09 1A5.07 5.07 0 0 0 5 4.77a5.44 5.44 0 0 0-1.5 3.78c0 5.42 3.3 6.61 6.44 7A3.37 3.37 0 0 0 9 18.13V22"></path></svg>
            ${p.cta || 'View Repository →'}
          </a>
        </div>
      </div>
    `).join('');

    const u = unit || units[i];
    const r = u.querySelector('.doorway').getBoundingClientRect();
    roomv.style.setProperty('--ox', (r.left + r.width / 2) + 'px');
    roomv.style.setProperty('--oy', (r.top + r.height * 0.55) + 'px');
    roomv.scrollTop = 0;
    units.forEach(x => x.classList.remove('swing'));
    u.classList.add('swing');
    document.body.style.overflow = 'hidden';
    clearTimeout(openRoom.t);
    openRoom.t = setTimeout(() => { roomv.classList.add('open'); initLC(); roomClose?.focus({ preventScroll: true }); }, 720);
  }

  function closeRoom() {
    clearTimeout(openRoom.t);
    roomv.classList.remove('open');
    document.body.style.removeProperty('overflow');
    setTimeout(() => { if (!roomv.classList.contains('open')) units.forEach(x => x.classList.remove('swing')); }, 950);
  }
  roomClose?.addEventListener('click', closeRoom);
  window.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && roomv.classList.contains('open')) closeRoom();
  });
})();

/* ================== TIMELINE STORY & 3D CLOCK TUNNEL ================== */
(() => {
  const sec = $('.story');
  if (!sec) return;
  const chs = $$('.ch', sec);
  const cols = $$('.dg__c', sec);
  const when = $('.story__when', sec);
  const count = $('.story__count', sec);
  const dot = $('.story__dot', sec);
  const tail = $('.story__tail', sec);
  const line = $('.story__line', sec);
  const cv = $('.story__bg', sec);
  if (!cv) return;
  const ctx = cv.getContext('2d');
  let W = 0, H = 0, dpr = Math.min(2, window.devicePixelRatio || 1);

  const size = () => {
    dpr = Math.min(2, window.devicePixelRatio || 1);
    W = cv.clientWidth;
    H = cv.clientHeight;
    cv.width = W * dpr;
    cv.height = H * dpr;
  };
  size();
  window.addEventListener('resize', size);

  // Time tunnel
  const RINGS = 14, GAP = 280, FOCAL = 480, R = 540;
  function tunnel(p, t) {
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, W, H);
    const cx = W * 0.5, cy = H * 0.52;
    const isDark = getMode() === 'dark';
    const rgb = isDark ? '232,228,224' : '26,24,24';
    const camZ = p * (chs.length - 1) * GAP * 1.5 + t * 15;
    const spin = -p * Math.PI * 1.4 - t * 0.02;
    const len = RINGS * GAP;

    for (let i = 0; i < RINGS; i++) {
      const z = ((i * GAP - camZ) % len + len) % len + 60;
      const s = (FOCAL / z) * 0.8;
      const fog = Math.min(1, Math.max(0, (z - 200) / 1000)) * Math.max(0, 1 - z / len);
      if (fog <= 0.01) continue;
      const rr = R * s;
      const rot = spin + i * 0.22;

      ctx.strokeStyle = `rgba(${rgb},${(fog * 0.14).toFixed(3)})`;
      ctx.lineWidth = Math.max(0.5, 1.2 * s);
      ctx.beginPath();
      ctx.arc(cx, cy, rr, 0, Math.PI * 2);
      ctx.stroke();

      // Clock tick marks
      const TICKS = 24;
      ctx.beginPath();
      for (let j = 0; j < TICKS; j++) {
        const a = rot + (j / TICKS) * Math.PI * 2;
        const l = (j % 6 === 0 ? 32 : 14) * s;
        ctx.moveTo(cx + Math.cos(a) * (rr - l), cy + Math.sin(a) * (rr - l));
        ctx.lineTo(cx + Math.cos(a) * rr, cy + Math.sin(a) * rr);
      }
      ctx.strokeStyle = `rgba(${rgb},${(fog * 0.2).toFixed(3)})`;
      ctx.lineWidth = Math.max(0.5, 1.5 * s);
      ctx.stroke();
    }
  }

  let shownIdx = -1;
  function setYear(y) {
    String(y).split('').forEach((digit, k) => {
      if (cols[k]) cols[k].style.setProperty('--d', digit);
    });
  }

  let p = 0;
  function updateScroll() {
    const r = line.getBoundingClientRect();
    const mid = window.innerHeight * 0.5;
    const totalH = line.offsetHeight;
    const travel = Math.min(totalH, Math.max(0, mid - r.top));
    p = travel / totalH;
    sec.style.setProperty('--p', p.toFixed(4));

    // Find active chapter
    let active = 0;
    chs.forEach((ch, idx) => {
      const cr = ch.getBoundingClientRect();
      if (cr.top <= mid + 60) active = idx;
    });

    if (active !== shownIdx) {
      shownIdx = active;
      chs.forEach((ch, idx) => ch.classList.toggle('on', idx === active));
      setYear(chs[active].dataset.y);
      when.textContent = chs[active].dataset.when;
      count.textContent = String(active + 1).padStart(2, '0');
      sec.dataset.ch = active;
    }
  }

  window.addEventListener('scroll', updateScroll, { passive: true });
  updateScroll();

  let t0 = performance.now();
  function loop(now) {
    tunnel(p, (now - t0) * 0.001);
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();

/* ================== 3D HOLOGRAPHIC ABILITY CARD ================== */
(() => {
  const holo = $('#holo');
  const holoOpen = $('#holoOpen');
  const holoClose = $('#holoClose');
  const holoLite = $('#holoLite');
  const holoLd = $('#holoLd');
  const hc = $('#hc');
  const ldBar = $('#ld-bar');
  const ldPct = $('#ld-pct');
  if (!holo || !holoOpen) return;

  holoOpen.addEventListener('click', () => {
    holo.hidden = false;
    holo.classList.add('on');
    holoLd.classList.remove('out', 'gone');
    holoLite.hidden = true;
    holoLite.classList.remove('in');
    document.body.style.overflow = 'hidden';

    // Simulate preloader progress
    let pct = 0;
    const interval = setInterval(() => {
      pct += 12;
      if (pct > 100) pct = 100;
      if (ldBar) ldBar.style.transform = `scaleX(${pct / 100})`;
      if (ldPct) ldPct.textContent = pct + '%';
      if (pct >= 100) {
        clearInterval(interval);
        setTimeout(() => {
          holoLd.classList.add('out');
          holoLite.hidden = false;
          holoLite.classList.add('in');
        }, 350);
      }
    }, 40);
  });

  function closeCard() {
    holo.classList.remove('on');
    setTimeout(() => {
      holo.hidden = true;
      document.body.style.removeProperty('overflow');
    }, 350);
  }
  holoClose?.addEventListener('click', closeCard);

  // 3D Card Tilt & Drag
  let held = false;
  hc?.addEventListener('pointermove', (e) => {
    const r = hc.getBoundingClientRect();
    const x = (e.clientX - r.left) / r.width - 0.5;
    const y = (e.clientY - r.top) / r.height - 0.5;
    hc.style.setProperty('--rx', (-y * 24).toFixed(2) + 'deg');
    hc.style.setProperty('--ry', (x * 24).toFixed(2) + 'deg');
    hc.style.setProperty('--px', (x * 2).toFixed(3));
    hc.style.setProperty('--py', (y * 2).toFixed(3));
    hc.style.setProperty('--lift', '1');
  });

  hc?.addEventListener('pointerleave', () => {
    hc.style.setProperty('--rx', '0deg');
    hc.style.setProperty('--ry', '0deg');
    hc.style.setProperty('--px', '0');
    hc.style.setProperty('--py', '0');
    hc.style.setProperty('--lift', '0');
  });

  // Flip card on click
  hc?.addEventListener('click', () => {
    hc.classList.toggle('flip');
  });
})();

