/* ================== BACK TO TOP ================== */
$('#backToTop')?.addEventListener('click', () => {
  if (window.__lenis) window.__lenis.scrollTo(0);
  else window.scrollTo({ top: 0, behavior: 'smooth' });
});

/* ================== PRELOADER COMPLETE ================== */
function startPreloader() {
  const loader = $('#loader');
  const ldNum = $('#ldNum');
  const ldBar = $('#ldBar');
  const pills = $$('.ld__pill');

  let p = 0;
  pills.forEach((pill, i) => {
    setTimeout(() => pill.classList.add('on'), 100 * i);
  });

  const progressInterval = setInterval(() => {
    p += 12;
    if (p > 100) p = 100;
    if (ldNum) ldNum.textContent = String(p).padStart(3, '0');
    if (ldBar) ldBar.style.transform = `scaleX(${p / 100})`;

    if (p >= 100) {
      clearInterval(progressInterval);
      setTimeout(() => {
        loader?.classList.add('out');
        document.body.classList.add('ready');
      }, 350);
    }
  }, 25);
}

if (document.readyState === 'complete' || document.readyState === 'interactive') {
  startPreloader();
} else {
  window.addEventListener('DOMContentLoaded', startPreloader);
  window.addEventListener('load', startPreloader);
}
// Absolute failsafe so loader NEVER blocks the user
setTimeout(() => {
  $('#loader')?.classList.add('out');
  document.body.classList.add('ready');
}, 1200);

/* ================== WORK DROPDOWN ================== */
(() => {
  const btn = $('#dropWork'), li = btn && btn.closest('.drop');
  if (!btn || !li) return;
  const set = (v) => { li.classList.toggle('open', v); btn.setAttribute('aria-expanded', String(v)); };
  btn.addEventListener('click', (e) => { e.stopPropagation(); set(!li.classList.contains('open')); });
  li.addEventListener('pointerenter', (e) => { if (e.pointerType === 'mouse') set(true); });
  li.addEventListener('pointerleave', (e) => { if (e.pointerType === 'mouse') set(false); });
  document.addEventListener('click', (e) => { if (!li.contains(e.target)) set(false); });
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape') set(false); });
  li.querySelectorAll('a').forEach(a => a.addEventListener('click', () => set(false)));
})();

/* nav turns light while the dark footer is under it */
(() => {
  const sf = document.querySelector('.sf'); if (!sf || !('IntersectionObserver' in window)) return;
  new IntersectionObserver(([e]) => document.body.classList.toggle('on-dark', e.isIntersecting && e.boundingClientRect.top < 80),
    { rootMargin: '0px 0px -92% 0px', threshold: 0 }).observe(sf);
})();
